def parse_numbers(num1_str, num2_str):
    """Helper function to parse numbers and handle ValueError."""
    try:
        num1 = float(num1_str)
        num2 = float(num2_str)
        return num1, num2, None
    except ValueError:
        return None, None, "Invalid input: Please provide valid numbers."

@app.route('/')
def home():
    """Home page for the calculator."""
    return render_template_string(HTML_TEMPLATE)

@app.route('/add/<num1_str>/<num2_str>')
def add(num1_str, num2_str):
    """Adds two numbers."""
    num1, num2, error = parse_numbers(num1_str, num2_str)
    if error:
        return render_template_string(HTML_TEMPLATE, error=error)
    result = num1 + num2
    return render_template_string(HTML_TEMPLATE, operation="Addition", num1=num1, num2=num2, result=result)

@app.route('/subtract/<num1_str>/<num2_str>')
def subtract(num1_str, num2_str):
    """Subtracts two numbers."""
    num1, num2, error = parse_numbers(num1_str, num2_str)
    if error:
        return render_template_string(HTML_TEMPLATE, error=error)
    result = num1 - num2
    return render_template_string(HTML_TEMPLATE, operation="Subtraction", num1=num1, num2=num2, result=result)

@app.route('/multiply/<num1_str>/<num2_str>')
def multiply(num1_str, num2_str):
    """Multiplies two numbers."""
    num1, num2, error = parse_numbers(num1_str, num2_str)
    if error:
        return render_template_string(HTML_TEMPLATE, error=error)
    result = num1 * num2
    return render_template_string(HTML_TEMPLATE, operation="Multiplication", num1=num1, num2=num2, result=result)

@app.route('/divide/<num1_str>/<num2_str>')
def divide(num1_str, num2_str):
    """Divides two numbers, handles division by zero."""
    num1, num2, error = parse_numbers(num1_str, num2_str)
    if error:
        return render_template_string(HTML_TEMPLATE, error=error)
    if num2 == 0:
        return render_template_string(HTML_TEMPLATE, error="Division by zero is not allowed.")
    result = num1 / num2
    return render_template_string(HTML_TEMPLATE, operation="Division", num1=num1, num2=num2, result=result)

if __name__ == '__main__':
    app.run(debug=True)

